-- Additive migration: all current About content becomes manageable from Admin and SQL.
-- Never overwrites existing edited values. Display labels do not alter game-level ranges or game IDs.
SET XACT_ABORT ON;
IF OBJECT_ID(N'dbo.Tbl_Web_About_Content',N'U') IS NULL
BEGIN
 CREATE TABLE dbo.Tbl_Web_About_Content(
  FieldKey nvarchar(120) NOT NULL CONSTRAINT PK_Tbl_Web_About_Content PRIMARY KEY,
  GroupKey nvarchar(60) NOT NULL, GroupName nvarchar(150) NOT NULL, Label nvarchar(250) NOT NULL,
  Value nvarchar(max) NOT NULL, DefaultValue nvarchar(max) NOT NULL,
  Kind varchar(20) NOT NULL, SortOrder int NOT NULL,
  UpdatedAt datetime2 NOT NULL CONSTRAINT DF_AboutContent_UpdatedAt DEFAULT SYSUTCDATETIME(),
  UpdatedBy nvarchar(100) NOT NULL CONSTRAINT DF_AboutContent_UpdatedBy DEFAULT N'migration',
  Revision rowversion NOT NULL,
  CONSTRAINT CK_AboutContent_Kind CHECK(Kind IN('short','multiline','image','url','toggle'))
 );
END;
IF OBJECT_ID(N'dbo.Tbl_Web_About_ContentHistory',N'U') IS NULL
BEGIN
 CREATE TABLE dbo.Tbl_Web_About_ContentHistory(
  HistoryId bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_Tbl_Web_About_ContentHistory PRIMARY KEY,
  FieldKey nvarchar(120) NOT NULL, OldValue nvarchar(max) NOT NULL, NewValue nvarchar(max) NOT NULL,
  ChangedAt datetime2 NOT NULL CONSTRAINT DF_AboutContentHistory_ChangedAt DEFAULT SYSUTCDATETIME(),
  ChangedBy nvarchar(128) NOT NULL
 );
END;
GO
