CREATE OR ALTER TRIGGER dbo.tr_Web_About_ContentHistory ON dbo.Tbl_Web_About_Content AFTER UPDATE AS
BEGIN
 SET NOCOUNT ON;
 INSERT dbo.Tbl_Web_About_ContentHistory(FieldKey,OldValue,NewValue,ChangedBy)
 SELECT i.FieldKey,d.Value,i.Value,CASE WHEN i.UpdatedBy<>d.UpdatedBy OR i.UpdatedAt<>d.UpdatedAt THEN i.UpdatedBy ELSE CONCAT(N'SQL: ',ORIGINAL_LOGIN()) END
 FROM inserted i JOIN deleted d ON d.FieldKey=i.FieldKey WHERE i.Value<>d.Value;
END;
GO
CREATE OR ALTER PROCEDURE dbo.sp_Web_About_Content AS
BEGIN
 SET NOCOUNT ON;
 SELECT FieldKey,GroupKey,GroupName,Label,Value,Kind,SortOrder,master.dbo.fn_varbintohexstr(Revision) Version,UpdatedAt,UpdatedBy
 FROM dbo.Tbl_Web_About_Content ORDER BY SortOrder,FieldKey;
END;
GO
CREATE OR ALTER PROCEDURE dbo.sp_Web_About_Admin_ContentSave @FieldsXml xml,@UpdatedBy nvarchar(100) AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 DECLARE @changes TABLE(FieldKey nvarchar(120),Value nvarchar(max),Version varchar(18));
 INSERT @changes SELECT n.f.value('@key','nvarchar(120)'),n.f.value('(value/text())[1]','nvarchar(max)'),n.f.value('@version','varchar(18)')
 FROM @FieldsXml.nodes('/fields/field') n(f);
 IF NOT EXISTS(SELECT 1 FROM @changes) OR EXISTS(SELECT FieldKey FROM @changes GROUP BY FieldKey HAVING COUNT(*)<>1)
  THROW 51000,N'Trường nội dung không hợp lệ.',1;
 IF EXISTS(SELECT 1 FROM @changes WHERE LEN(Version)<>18 OR LEFT(Version,2)<>'0x' OR SUBSTRING(Version,3,16) LIKE '%[^0123456789ABCDEFabcdef]%')
  THROW 51001,N'Phiên bản dữ liệu không hợp lệ. Vui lòng tải lại trang.',1;
 BEGIN TRANSACTION;
 BEGIN TRY
  IF EXISTS(SELECT 1 FROM @changes c LEFT JOIN dbo.Tbl_Web_About_Content f WITH(UPDLOCK,HOLDLOCK) ON f.FieldKey=c.FieldKey
   WHERE f.FieldKey IS NULL OR c.Version IS NULL OR master.dbo.fn_varbintohexstr(f.Revision)<>c.Version)
   THROW 51001,N'Nội dung đã thay đổi. Vui lòng tải lại trang trước khi lưu.',1;
  IF EXISTS(SELECT 1 FROM @changes c JOIN dbo.Tbl_Web_About_Content f ON f.FieldKey=c.FieldKey
   WHERE DATALENGTH(c.Value)>CASE WHEN f.Kind='multiline' THEN 40000 WHEN f.Kind IN('image','url') THEN 4000 ELSE 1000 END
   OR (f.Kind='toggle' AND c.Value NOT IN(N'0',N'1')))
   THROW 51000,N'Giá trị nội dung không hợp lệ.',1;
  UPDATE f SET Value=c.Value,UpdatedAt=SYSUTCDATETIME(),UpdatedBy=@UpdatedBy
  FROM dbo.Tbl_Web_About_Content f JOIN @changes c ON c.FieldKey=f.FieldKey;
  COMMIT TRANSACTION;
 END TRY
 BEGIN CATCH
  IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
  THROW;
 END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE dbo.sp_Web_About_Admin_ContentHistory @FieldKey nvarchar(120)=NULL,@Page int=1 AS
BEGIN
 SET NOCOUNT ON;
 IF @Page<1 SET @Page=1;
 ;WITH history AS(
 SELECT h.HistoryId,h.FieldKey,ISNULL(f.Label,h.FieldKey) Label,h.OldValue,h.NewValue,h.ChangedAt,h.ChangedBy,
 ROW_NUMBER() OVER(ORDER BY h.HistoryId DESC) RowNumber
 FROM dbo.Tbl_Web_About_ContentHistory h LEFT JOIN dbo.Tbl_Web_About_Content f ON f.FieldKey=h.FieldKey
 WHERE @FieldKey IS NULL OR h.FieldKey=@FieldKey)
 SELECT HistoryId,FieldKey,Label,OldValue,NewValue,ChangedAt,ChangedBy FROM history
 WHERE RowNumber>(CONVERT(bigint,@Page)-1)*50 AND RowNumber<=CONVERT(bigint,@Page)*50 ORDER BY HistoryId DESC;
END;
GO
